# context-transfer-request.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$defs": {
    "endpoint": {
      "additionalProperties": false,
      "properties": {
        "host_id": {
          "pattern": "^host-[a-z0-9-]+$",
          "type": "string"
        },
        "principal_id": {
          "pattern": "^pr-[a-z0-9-]+$",
          "type": "string"
        },
        "profile_id": {
          "not": {
            "const": "default"
          },
          "pattern": "^pf-[a-z0-9-]+$",
          "type": "string"
        },
        "session_id": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "principal_id",
        "profile_id",
        "host_id",
        "session_id"
      ],
      "type": "object"
    }
  },
  "$id": "https://coding-hermes.local/chd32/schemas/context-transfer-request.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "capability_probe_ref": {
      "pattern": "^probe-[a-z0-9-]+$",
      "type": "string"
    },
    "import_mode": {
      "enum": [
        "authorized_archive_reference",
        "authorized_checkpoint_reference"
      ]
    },
    "parent_bond_id": {
      "pattern": "^b-[0-9]{8}-[0-9]{4}-[a-z0-9-]+$",
      "type": "string"
    },
    "parent_session_id": {
      "minLength": 1,
      "type": "string"
    },
    "policy_owner": {
      "pattern": "^pr-[a-z0-9-]+$",
      "type": "string"
    },
    "request_id": {
      "pattern": "^ctxreq-[a-z0-9-]+$",
      "type": "string"
    },
    "room_id": {
      "pattern": "^(obj|task|space)-[a-z0-9-]+$",
      "type": "string"
    },
    "schema_version": {
      "const": 1
    },
    "selected_refs": {
      "items": {
        "minLength": 1,
        "type": "string"
      },
      "minItems": 1,
      "type": "array"
    },
    "source": {
      "$ref": "#/$defs/endpoint"
    },
    "target": {
      "$ref": "#/$defs/endpoint"
    },
    "thread_root": {
      "minimum": 1,
      "type": "integer"
    },
    "work_uid": {
      "pattern": "^work-[A-Za-z0-9][A-Za-z0-9._-]*$",
      "type": "string"
    }
  },
  "required": [
    "schema_version",
    "request_id",
    "source",
    "target",
    "room_id",
    "thread_root",
    "work_uid",
    "parent_bond_id",
    "parent_session_id",
    "policy_owner",
    "import_mode",
    "selected_refs",
    "capability_probe_ref"
  ],
  "title": "CHD cross-profile context transfer request",
  "type": "object"
}
```
